// Chỉ xử lý link TikTok/YouTube thành viên gửi trong nhóm OA (GMF); chat 1-1 với OA để dành cho khách
// và tin OA tự gửi vào nhóm (oa_send_group_*) bị bỏ qua để không tự trả lời chính mình
const out = [];
const TA_RX = /^\/(themanh|thêmảnh|them_anh|thêm_ảnh)\s*#?\s*(\d+)\b(?:\s+(fb|face|facebook|zalo|oa)\b)?/i;
const DT_RX = /^\/(datanh|đặtảnh|dat_anh|đặt_ảnh|doianh|đổiảnh|bothaanh)\s*#?\s*(\d+)\b/i;
const KENH = (s) => /^(fb|face|facebook)$/i.test(s || '') ? 'fb' : /^(zalo|oa)$/i.test(s || '') ? 'zalo' : '';
// Ảnh chờ 15 phút lưu trong Data Table "anh_cho_zalo" (mỗi ảnh 1 dòng; gửi nhiều ảnh cùng lúc không bị ghi đè).
// Lệnh cần ảnh chờ -> canCho: true; node "Gộp ảnh chờ" ghép ảnh chờ vào lệnh rồi xóa.
for (const item of $input.all()) {
  const e = item.json.body || {};
  // Ảnh gửi vào nhóm: ghi chú "/dunganh <số>" -> dùng ảnh này cho bài; không có lệnh -> nhớ ảnh 15 phút để gõ /dunganh sau
  const DA_RX = /^\/(dunganh|dùngảnh|dung_anh|dùng_ảnh|anhtay|ảnhtay|anh_tay|ảnh_tay)\s*#?\s*(\d+)\b(?:\s+(fb|face|facebook|zalo|oa)\b)?/i;
  if (e.event_name === 'user_send_group_image' || e.event_name === 'user_send_group_file') {
    // ảnh thường, hoặc FILE ảnh gốc (png/jpg/webp, không bị Zalo nén) gửi bằng nút đính kèm tệp
    const atts = (e.message?.attachments || []).filter(x => x.type === 'image' || /\.(png|jpe?g|webp)$/i.test(String(x.payload?.name || x.payload?.url || '')));
    const urls = atts.map(x => x.payload?.url).filter(Boolean);
    const url = urls[urls.length - 1] || '';
    const dti = (e.message?.text || '').trim().match(DT_RX);
    if (dti && urls.length) {
      out.push({ json: { route: 'datanh', canCho: true, id: dti[2], urls, user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
    const tam = (e.message?.text || '').trim().match(TA_RX);
    if (tam && urls.length) {
      out.push({ json: { route: 'themanh', canCho: true, id: tam[2], kenh: KENH(tam[3]), urls, user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
    const dm = (e.message?.text || '').trim().match(DA_RX);
    const bmi = String(e.message?.text || '').replace(/^\s+/, '').match(/^\/(baimoi|bàimới|bai_moi|bài_mới|nhapbai|nhậpbài|nhap_bai)\b([\s\S]*)$/i);
    if (bmi && url) { out.push({ json: { route: 'baimoi', canCho: true, noidung: (bmi[2] || '').trim(), url, urls, user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
    const tdi = (e.message?.text || '').trim().match(/^\/(tieude|tiêuđề|tieu_de)\b\s*([\s\S]*)$/i);
    if (tdi && url) { out.push({ json: { route: 'tieude', title: tdi[2].trim(), url, user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
    if (dm && url) out.push({ json: { route: 'dunganh', id: dm[2], kenh: KENH(dm[3]), url, user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    else if (url) urls.forEach((u, i) => out.push({ json: { route: 'luuanh', user_id: String(e.sender?.id || ''), url: u, ts: (Number(e.timestamp) || Date.now()) * 10 + i, group_id: e.recipient?.id } }));
    continue;
  }
  if (!['user_send_group_text', 'user_send_group_link'].includes(e.event_name)) continue;
  // Lệnh /datanh <số>: thay CẢ BỘ ảnh bằng các ảnh gửi trong 15 phút (workflow Đặt bộ ảnh)
  const dt = (e.message?.text || '').trim().match(DT_RX);
  if (dt) {
    out.push({ json: { route: 'datanh', canCho: true, id: dt[2], urls: [], user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
  const tam = (e.message?.text || '').trim().match(TA_RX);
  if (tam) {
    out.push({ json: { route: 'themanh', canCho: true, id: tam[2], kenh: KENH(tam[3]), urls: [], user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
  // Lệnh /baimoi + xuống dòng + bài tự viết (cùng 1 tin): nhập bài thành dòng Chờ duyệt, KHÔNG qua AI; ảnh gửi trước 15 phút thì dùng làm ảnh bài
  const bm = String(e.message?.text || '').replace(/^\s+/, '').match(/^\/(baimoi|bàimới|bai_moi|bài_mới|nhapbai|nhậpbài|nhap_bai)\b([\s\S]*)$/i);
  if (bm) {
    out.push({ json: { route: 'baimoi', canCho: true, noidung: (bm[2] || '').trim(), url: '', urls: [], user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
  // /xemtruoc <số> [giờ]: đăng ẨN để xem trước; /congkhai <số> [giờ|huy]: công khai bản ẩn (workflow Xem trước & công khai)
  const xt = (e.message?.text || '').trim().match(/^\/(xemtruoc|xemtrước|xem_truoc|xem_trước|dangan|đăngẩn|dang_an)\s*#?\s*(\d+)\b\s*([\s\S]*)$/i);
  if (xt) { out.push({ json: { route: 'xemtruoc', id: xt[2], gio: (xt[3] || '').trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
  const ck = (e.message?.text || '').trim().match(/^\/(congkhai|côngkhai|cong_khai|công_khai|public)\s*#?\s*(\d+)\b\s*([\s\S]*)$/i);
  if (ck) { out.push({ json: { route: 'congkhai', id: ck[2], gio: (ck[3] || '').trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
  // /xemanh <số>: xem cả bộ ảnh của bài (ảnh lưới đánh số) – workflow Thêm ảnh cho bài
  const xem = (e.message?.text || '').trim().match(/^\/(xemanh|xemảnh|xem_anh|xem_ảnh|boanh|bộảnh|dsanh)\s*#?\s*(\d+)\s*$/i);
  if (xem) { out.push({ json: { route: 'xemanh', id: xem[2], user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
  // /xepanh <số> <thứ tự mới>: đổi thứ tự ảnh (workflow Thêm ảnh cho bài)
  const xp = (e.message?.text || '').trim().match(/^\/(xepanh|xếpảnh|xep_anh|xếp_ảnh|thutuanh|doithutu)\s*#?\s*(\d+)\b\s*([\s\S]*)$/i);
  if (xp) { out.push({ json: { route: 'xepanh', id: xp[2], arg: (xp[3] || '').trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
  const xa = (e.message?.text || '').trim().match(/^\/(xoaanh|xóaảnh|xoa_anh|xóa_ảnh|boanh|bỏảnh)\s*#?\s*(\d+)\b\s*([\s\S]*)$/i);
  if (xa) { out.push({ json: { route: 'xoaanh', id: xa[2], arg: (xa[3] || '').trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
  const da = (e.message?.text || '').trim().match(DA_RX);
  if (da) {
    out.push({ json: { route: 'dunganh', canCho: true, id: da[2], kenh: KENH(da[3]), url: '', user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    continue;
  }
  // Lệnh /tieude <tiêu đề> (viết bài ngay theo tiêu đề) và /dstieude (xem tiêu đề đang chờ) chuyển sang workflow AI viết bài
  const td = (e.message?.text || '').trim().match(/^\/(tieude|tiêuđề|tieu_de)\b\s*([\s\S]*)$/i);
  if (td) {
    // vừa gửi ảnh/file ảnh trong 15 phút -> dùng luôn ảnh đó cho bài
    out.push({ json: { route: 'tieude', canCho: true, title: td[2].trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    continue;
  }
  if (/^\/(dstieude|dstiêuđề|ds_tieude)\s*$/i.test((e.message?.text || '').trim())) {
    out.push({ json: { route: 'dstieude', user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    continue;
  }
  // Lệnh /choduyet: xem danh sách bài chờ duyệt / chờ đăng (workflow Duyệt bài)
  if (/^\/(choduyet|chờduyệt|cho_duyet|chờ_duyệt|dsduyet|dsbai)\s*$/i.test((e.message?.text || '').trim())) {
    out.push({ json: { route: 'duyet', action: 'list', id: '0', user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    continue;
  }
  // Lệnh /anhbia <số> [yêu cầu]: tạo lại ảnh bìa ngang 16:9 cho Zalo OA (workflow Tạo ảnh bìa Zalo OA)
  const ab = (e.message?.text || '').trim().match(/^\/(anhbia|ảnhbìa|anh_bia|ảnh_bìa|anhbìa)\s*#?\s*(\d+)\b\s*([\s\S]*)$/i);
  if (ab) {
    out.push({ json: { route: 'anhbia', nguon: 'anhbia', id: ab[2], request: (ab[3] || '').trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    continue;
  }
  // Lệnh /xem <số> chu|anh <số bản>: gửi toàn văn / ảnh của 1 bản cũ để đọc (workflow Sửa bài từ Zalo)
  const xm = (e.message?.text || '').trim().match(/^\/(xem)\s*#?\s*(\d+)\s*((?:ảnh\s*bìa|anh\s*bia|anh_bia|ảnh_bìa|bìa|bia|chu|chữ|anh|ảnh)?\s*\d*)\s*$/i);
  if (xm) {
    out.push({ json: { route: 'xem', id: xm[2], request: (xm[3] || '').trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    continue;
  }
  // Lệnh /lichsu <số> [chu|anh]: xem các bản chữ/ảnh đã có của bài (workflow Sửa bài từ Zalo)
  const ls = (e.message?.text || '').trim().match(/^\/(lichsu|lịchsử|lich_su|lịch_sử|history)\s*#?\s*(\d+)\s*(ảnh\s*bìa|anh\s*bia|anh_bia|ảnh_bìa|bìa|bia|chu|chữ|anh|ảnh)?\s*$/i);
  if (ls) {
    out.push({ json: { route: 'lichsu', id: ls[2], request: ls[3] || '', user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    continue;
  }
  // Lệnh /dungbai <số> + xuống dòng + bài tự viết (cùng 1 tin): thay toàn bộ chữ (workflow Sửa bài từ Zalo)
  const db = String(e.message?.text || '').replace(/^\s+/, '').match(/^\/(dungbai|dùngbài|dung_bai|dùng_bài|baicuatoi)\s*#?\s*(\d+)\b([\s\S]*)$/i);
  if (db) { out.push({ json: { route: 'dungbai', id: db[2], request: (db[3] || '').trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
  // Lệnh /hoantac <số>: quay lại bản trước lần sửa gần nhất (workflow Sửa bài từ Zalo)
  const ht = (e.message?.text || '').trim().match(/^\/(hoantac|hoàntác|hoan_tac|hoàn_tác|undo|quaylai|quaylại)\s*#?\s*(\d+)\s*((?:ảnh\s*bìa|anh\s*bia|anh_bia|ảnh_bìa|bìa|bia|chu|chữ|anh|ảnh)?\s*\d*)\s*$/i);
  if (ht) {
    out.push({ json: { route: 'hoantac', id: ht[2], request: (ht[3] || '').trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    continue;
  }
  // Lệnh /sua <số> <yêu cầu> (AI sửa chữ) và /anh <số> [yêu cầu] (tạo lại ảnh) chuyển sang workflow Sửa bài từ Zalo
  const sua = (e.message?.text || '').trim().match(/^\/(sua|sửa)\s*#?\s*(\d+)\b\s*([\s\S]*)$/i);
  const anh = (e.message?.text || '').trim().match(/^\/(anh|ảnh)\s*#?\s*(\d+)\b\s*([\s\S]*)$/i);
  if (sua || anh) {
    const m = sua || anh;
    out.push({ json: { route: sua ? 'sua' : 'anh', id: m[2], request: m[3].trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    continue;
  }
  // Lệnh /duyet <số> hoặc /bo <số> chuyển sang workflow Duyệt bài từ Zalo
  // /hengio <số> <giờ> [ngày] | huy: đặt / bỏ giờ đăng riêng cho bài (workflow Duyệt bài)
  const hg = (e.message?.text || '').trim().match(/^\/(hengio|hẹngiờ|hen_gio|hẹn_giờ|dangluc|đănglúc)\s*#?\s*(\d+)\b\s*([\s\S]*)$/i);
  if (hg) { out.push({ json: { route: 'duyet', action: 'hengio', id: hg[2], gio: (hg[3] || '').trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } }); continue; }
  const dv = (e.message?.text || '').trim().match(/^\/(duyet|duyệt|bo|bỏ)\s*#?\s*(\d+)\b\s*([\s\S]*)$/i);
  if (dv) {
    out.push({ json: { route: 'duyet', action: /^d/i.test(dv[1]) ? 'duyet' : 'bo', id: dv[2], gio: /^b/i.test(dv[1]) ? '' : (dv[3] || '').trim(), user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id } });
    continue;
  }
  // Lệnh /ads <mô tả> chuyển sang workflow Zalo OA - Ads Image
  const ads = (e.message?.text || '').trim().match(/^\/ads\b\s*([\s\S]*)$/i);
  if (ads) {
    out.push({ json: { route: 'ads', user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id, brief: ads[1].trim() } });
    continue;
  }
  const text = [e.message?.text, ...(e.message?.attachments || []).map((a) => a.payload?.url)]
    .filter(Boolean)
    .join(' ');
  let url = (text.match(/https?:\/\/\S+/) || [])[0];
  if (!url) continue;
  let platform = null;
  if (/tiktok\.com/i.test(url)) platform = 'tiktok';
  else if (/youtube\.com|youtu\.be/i.test(url)) platform = 'youtube';
  if (!platform) continue;
  // Đưa mọi dạng link YouTube (shorts, youtu.be, live, embed) về watch?v=ID
  if (platform === 'youtube') {
    const id = (url.match(/(?:v=|youtu\.be\/|shorts\/|live\/|embed\/)([\w-]{11})/) || [])[1];
    if (!id) continue;
    url = `https://www.youtube.com/watch?v=${id}`;
  }
  // Sự kiện nhóm: recipient.id là group_id, oa_id nằm ở cấp ngoài
  out.push({ json: { route: 'content', user_id: e.sender?.id, group_id: e.recipient?.id, oa_id: e.oa_id, msg_id: e.message?.msg_id, url, platform } });
}
return out;

// Gửi bài vào nhóm: đầu tin có số bài, cuối tin hướng dẫn thêm ảnh rồi duyệt. Zalo giới hạn ~2000 ký tự/tin
const b = $('Chuẩn bị dòng video').first().json;
const id = b.id;
const max = 1900;
const parts = [`📝 BÀI #${id} CHỜ DUYỆT (viết từ video)\n🖼️ Bài CHƯA CÓ ẢNH, thêm ảnh rồi mới /duyet được.`];
let cur = '';
for (const para of String(b.noiDung).split(/\n{2,}/)) {
  const joined = cur ? cur + '\n\n' + para : para;
  if (joined.length <= max) { cur = joined; continue; }
  if (cur) parts.push(cur);
  cur = '';
  if (para.length <= max) { cur = para; continue; }
  for (let i = 0; i < para.length; i += max) parts.push(para.slice(i, i + max));
}
if (cur) parts.push(cur);
parts.push([
  `🖼️ THÊM ẢNH CHO BÀI #${id}:`,
  `• Ảnh tự thiết kế: gửi ảnh vào nhóm (kèm ghi chú "/dunganh ${id}" hoặc gõ "/dunganh ${id}" trong 15 phút). Ảnh vuông = ảnh bài, ảnh ngang = ảnh bìa Zalo OA`,
  `• Cả bộ ảnh (vuông + ngang, Fanpage + Zalo): gửi hết ảnh rồi gõ "/datanh ${id}"`,
  `• Thêm lẻ ảnh vào album: gửi ảnh rồi gõ "/themanh ${id}"`,
  `• Ảnh bìa Zalo OA từ ảnh bài: "/anhbia ${id}"`,
  `• Muốn AI vẽ ảnh: "/anh ${id} <yêu cầu>"`,
  ``,
  `✏️ "/sua ${id} <yêu cầu>" AI sửa chữ · 📝 "/dungbai ${id}" + xuống dòng dán bài tự viết`,
  `👉 Đủ ảnh thì "/duyet ${id} [giờ]" để đăng, "/bo ${id}" để bỏ`,
].join('\n'));
return parts.map((part, i) => ({ json: { part, index: i + 1 } }));

// Bài viết từ link video -> 1 dòng mới trên Sheet lịch đăng, trạng thái Chờ duyệt, KHÔNG có ảnh (người phụ trách tự thêm ảnh)
let text = '';
try { text = $('Create Content Paid').first().json.text || ''; } catch (e) {}
if (!text) { try { text = $('Create Content').first().json.text || ''; } catch (e) {} }
text = String(text).replace(/\r/g, '').replace(/\*\*/g, '').replace(/^#+\s*/gm, '').replace(/`/g, '').replace(/\n{3,}/g, '\n\n').trim();
if (!text) throw new Error('AI không trả nội dung bài');
const FOOTER = ['---***---', 'CÔNG TY TNHH GOSTECH', 'Giải pháp phát triển doanh nghiệp',
  '📍 Trụ sở chính: Số nhà 11, ngõ 245/116/27 Phố Định Công, Phường Định Công, Hà Nội',
  '📍 Văn phòng: Tòa A3 Vinhomes Hàm Nghi, Phường Từ Liêm, Hà Nội', '📞 Hotline: 0968 343 342',
  '🌐 Website: gostech.vn | hocviendigital.vn'].join('\n');
const noiDung = text + '\n\n' + FOOTER;
const tieuDe = (text.split('\n').find(l => l.trim()) || '').trim().slice(0, 200);
const rows = $('Đọc lịch đăng (video)').all().map(i => i.json).filter(r => r && r.row_number);
const id = rows.reduce((m, r) => Math.max(m, Number(r['ID']) || 0), 0) + 1;
// Ghi vào ô vàng trống đầu tiên (Chờ viết, chưa có tiêu đề/nội dung); hết ô vàng thì thêm dòng mới
const vang = rows.find(r => !String(r['Tiêu đề'] || '').trim() && !String(r['Nội dung'] || '').trim()
  && String(r['Trạng thái'] || '').trim() === 'Chờ viết');
const ev = $('Parse Event').first().json;
const now = DateTime.now().setZone('Asia/Ho_Chi_Minh').toFormat('dd/MM/yyyy HH:mm');
const row = { 'ID': String(id), 'Tiêu đề': tieuDe, 'Nội dung': noiDung, 'Trạng thái': 'Chờ duyệt',
  'Ghi chú': `AI viết từ video ${ev.platform || ''} ${now}: ${ev.url || ''} | chưa có ảnh` };
return [{ json: { id, tieuDe, noiDung, coVang: !!vang, row_number: vang ? vang.row_number : null, row } }];

// /baimoi + xuống dòng + bài tự viết: nhập nguyên văn (KHÔNG qua AI) thành 1 dòng Chờ duyệt trên Sheet
const ev = $('Is Bài mới?').first().json;
const FOOTER = ['---***---', 'CÔNG TY TNHH GOSTECH', 'Giải pháp phát triển doanh nghiệp',
  '📍 Trụ sở chính: Số nhà 11, ngõ 245/116/27 Phố Định Công, Phường Định Công, Hà Nội',
  '📍 Văn phòng: Tòa A3 Vinhomes Hàm Nghi, Phường Từ Liêm, Hà Nội', '📞 Hotline: 0968 343 342',
  '🌐 Website: gostech.vn | hocviendigital.vn'].join('\n');
let text = String(ev.noidung || '').replace(/\r/g, '').split('---***---')[0]
  .replace(/\*\*/g, '').replace(/`/g, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const lines = text.split('\n').filter(l => l.trim());
const base = { group_id: ev.group_id, oa_id: ev.oa_id, user_id: ev.user_id, url: ev.url || '', urls: (ev.urls && ev.urls.length ? ev.urls : (ev.url ? [ev.url] : [])) };
if (lines.length < 2 || text.split(/\s+/).length < 15) {
  return [{ json: { ...base, ok: false, reply: 'ℹ️ Cách nhập bài tự viết (không qua AI), gõ trong CÙNG 1 tin:\n/baimoi\nTIÊU ĐỀ BÀI VIẾT\nNội dung bài…\n\n(Dòng đầu là tiêu đề, phần dưới là nội dung, bài tối thiểu khoảng 15 chữ. Có thể gửi ảnh trước đó trong 15 phút hoặc gửi ảnh kèm ghi chú /baimoi để dùng làm ảnh bài.)' } }];
}
const tieuDe = lines[0].trim().slice(0, 200);
const noiDung = text + '\n\n' + FOOTER;
const rows = $('Đọc lịch đăng (bài mới)').all().map(i => i.json).filter(r => r && r.row_number);
const id = rows.reduce((m, r) => Math.max(m, Number(r['ID']) || 0), 0) + 1;
const vang = rows.find(r => !String(r['Tiêu đề'] || '').trim() && !String(r['Nội dung'] || '').trim() && String(r['Trạng thái'] || '').trim() === 'Chờ viết');
const now = DateTime.now().setZone('Asia/Ho_Chi_Minh').toFormat('dd/MM/yyyy HH:mm');
const row = { 'ID': String(id), 'Tiêu đề': tieuDe, 'Nội dung': noiDung, 'Trạng thái': 'Chờ duyệt',
  'Ghi chú': `Bài tự viết nhập qua Zalo ${now} (không qua AI)${base.url ? ` | ${base.urls.length} ảnh gửi kèm` : ' | chưa có ảnh'}` };
const soChu = text.split(/\s+/).filter(Boolean).length;
const reply = [
  `📝 BÀI #${id} ĐÃ NHẬP (bài tự viết, không qua AI) – Chờ duyệt`,
  `Tiêu đề: ${tieuDe}`,
  `(${soChu} chữ, đã gắn chữ ký GOSTECH)`,
  '',
  base.url ? `🖼️ Đang đặt ${base.urls.length} ảnh vừa gửi cho bài #${id} (vuông đầu = ảnh chính, ngang đầu = ảnh bìa Zalo OA + đầu album Fanpage)...` : `🖼️ Bài CHƯA CÓ ẢNH: gửi ảnh vào nhóm rồi gõ "/dunganh ${id}" (ảnh vuông = ảnh bài, ảnh ngang = ảnh bìa Zalo OA)`,
  `🖼️ Cả bộ ảnh (vuông + ngang): gửi hết ảnh rồi "/datanh ${id}" · ➕ Thêm lẻ: "/themanh ${id}" · Bìa Zalo OA từ ảnh bài: "/anhbia ${id}"`,
  `✏️ Sửa: "/dungbai ${id}" + bài mới · "/sua ${id} <yêu cầu>" (AI) · "/xem ${id} chu 1"`,
  `👉 Đủ ảnh thì "/duyet ${id} [giờ]" để đăng, "/bo ${id}" để bỏ`,
].join('\n');
return [{ json: { ...base, ok: true, id, coVang: !!vang, row_number: vang ? vang.row_number : null, row, reply } }];

// Ảnh gửi kèm /baimoi (1 hoặc nhiều) -> Đặt bộ ảnh (vuông đầu = ảnh chính, ngang đầu = bìa Zalo OA, còn lại = ảnh thêm)
const b = $('Chuẩn bị bài mới').first().json;
return [{ json: { route: 'datanh', id: String(b.id), urls: b.urls, user_id: b.user_id, group_id: b.group_id, oa_id: b.oa_id } }];

// Ghép ảnh gửi trong 15 phút (theo thứ tự gửi) vào lệnh
const ev = $('Cần ảnh chờ?').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.url && Date.now() - Number(r.ts) / 10 < 15 * 60 * 1000)
  .sort((a, b) => Number(a.ts) - Number(b.ts) || Number(a.id) - Number(b.id));
const uniq = (a) => [...new Set(a.filter(Boolean))];
const cho = uniq(rows.map(r => r.url));
const o = { ...ev, soAnhCho: cho.length };
if (['datanh', 'themanh'].includes(ev.route)) o.urls = uniq([...cho, ...(ev.urls || [])]);
else if (ev.route === 'baimoi') { o.urls = uniq([...cho, ...(ev.urls || [])]); o.url = o.urls[o.urls.length - 1] || ''; }
else if (['dunganh', 'tieude'].includes(ev.route)) { if (!ev.url && cho.length) o.url = cho[cho.length - 1]; }
return [{ json: o }];
